import { Component } from "react";

class counter extends Component{

    constructor(){
        super();

        this.state={
            count:0
        };
    }

    increase =()=>{
        this.setState({
            count:this.state.count +1
        });
    };
    render(){
        return (
            <div>
                <h2>Count:{this.state.count}</h2>
                <button onClick={this.increase}>increase</button>
            </div>
        )
    }
}

export default counter;
